      function SubmitButton() {
        const button = document.createElement("button");
        button.type = "submit";
        button.textContent = "Contact support";
        return button;
      }

      function SupportContactForm() {
        const fragment = document.createDocumentFragment();
        fields.forEach((field) => fragment.append(Field(field)));
        fragment.append(SubmitButton());
        return fragment;
      }

      document.getElementById("form-root").append(SupportContactForm());
    </script>
