   <body>
     <main class="support-card" aria-labelledby="support-title">
       <p class="eyebrow">Support team</p>
       <h1 id="support-title">How can we help?</h1>
       <p class="intro">
         Send your contact details and a support specialist will reach out with the next steps.
       </p>

       <form id="support-form">
         <div id="form-root"></div>
       </form>
     </main>

     <script>
       const fields = [
         {
           id: "full-name",
           label: "Full name",
           name: "fullName",
           type: "text",
           placeholder: "Jane Doe",
           autoComplete: "name",
           required: true
         },
         {
           id: "email-address",
           label: "Email address",
           name: "email",
           type: "email",
           placeholder: "jane@example.com",
           autoComplete: "email",
           required: true
         },
         {
           id: "phone-number",
           label: "Phone number",
           name: "phone",
           type: "tel",
           placeholder: "(555) 123-4567",
           autoComplete: "tel",
           helperText: "Use a 10-digit phone number, such as (555) 123-4567.",
           required: false
         }
       ];

       function Field({ id, label, name, type, placeholder, autoComplete, helperText, required }) {
         const wrapper = document.createElement("div");
         wrapper.className = "form-field";

         const labelElement = document.createElement("label");
         labelElement.htmlFor = id;
         labelElement.textContent = label;

         if (!required) {
           const optionalText = document.createElement("span");
           optionalText.className = "optional";
           optionalText.textContent = " (optional)";
           labelElement.append(optionalText);
         }

         const input = document.createElement("input");
         input.id = id;
         input.name = name;
         input.type = type;
         input.placeholder = placeholder;
         input.autocomplete = autoComplete;
         input.required = required;

         if (helperText) {
           const helperId = `${id}-help`;
           const helper = document.createElement("p");
           helper.id = helperId;
           helper.className = "helper-text";
           helper.textContent = helperText;
           input.setAttribute("aria-describedby", helperId);
           wrapper.append(labelElement, input, helper);
           return wrapper;
         }

         wrapper.append(labelElement, input);
         return wrapper;
       }

       function SubmitButton() {
         const button = document.createElement("button");
         button.type = "submit";
         button.textContent = "Contact support";
         return button;
       }

       function SupportContactForm() {
         const fragment = document.createDocumentFragment();
         fields.forEach((field) => fragment.append(Field(field)));
         fragment.append(SubmitButton());
         return fragment;
       }

       document.getElementById("form-root").append(SupportContactForm());
     </script>
   </body>
 </html>

